}

// paintMonograms(): with no crest picked, the plate shows the club's initials instead.
function initialsOf(name) {
  var words = String(name || '').trim().split(/[\s\-]+/);
  var out = '';
  for (var i = 0; i < words.length && out.length < 2; i++) {
    var c = words[i].charAt(0);
    if (c && c.toUpperCase() !== c.toLowerCase()) out += c.toUpperCase();
  }
  return out;
}
function paintMonograms() {
  var pairs = [['.scoreboard-team-a .scoreboard-monogram', 'f0'], ['.scoreboard-team-b .scoreboard-monogram', 'f2']];
  for (var i = 0; i < pairs.length; i++) {
