  }
}

// periodName(n): "{n}. TŘETINA" for regulation, the overtime word after it.
function periodName(n) {
  if (n > regulationPeriods()) return fieldText('f12');
  return fieldText('f11').replace(/\{n\}/g, String(n));
}
function paintPeriodName() {
  var el = document.querySelector('.scoreboard-period-name');
  var root = document.querySelector('.scoreboard');
  var n = Math.max(1, fieldInt('f4'));
  if (el) el.textContent = periodName(n);
  if (root) root.classList.toggle('scoreboard-ot', n > regulationPeriods());
}

// paintStatus(): the word in the chip follows the root's state classes.
function paintStatus() {
  var root = document.querySelector('.scoreboard');
  var el = document.querySelector('.scoreboard-status');
  if (!root || !el) return;
  if (root.classList.contains('scoreboard-final')) el.textContent = fieldText('f15');
  else if (root.classList.contains('scoreboard-break')) el.textContent = fieldText('f14');
  else el.textContent = '';
}

// rebuildPeriods(): goals per period. Finished periods come from f6 ("period | A | B" per
// line); the CURRENT period is always the live total minus the others, so a goal button moves
// the right column by itself and the breakdown always adds up to the score.
function rebuildPeriods() {
  var wrap = document.getElementById('scoreboard-periods');
  if (!wrap) return;
  var current = Math.max(1, fieldInt('f4'));
  var reg = regulationPeriods();
  var known = {};
  var lines = fieldText('f6').split('\n');
  var maxListed = 0;
  for (var i = 0; i < lines.length; i++) {
    var parts = lines[i].split('|');
    if (parts.length < 3) continue;
    var label = parts[0].replace(/[^0-9A-Za-z]/g, '');
    var idx = parseInt(label, 10);
    if (!isFinite(idx)) idx = label === '' ? NaN : reg + 1;   // "OT", "P" ... is the overtime
    if (!isFinite(idx) || idx < 1) continue;
    known[idx] = [parseInt(parts[1], 10) || 0, parseInt(parts[2], 10) || 0];
    if (idx > maxListed) maxListed = idx;
  }
  var cols = Math.max(reg, Math.min(current, reg + 1), Math.min(maxListed, reg + 1));
  var cur = Math.min(current, reg + 1);
  var otherA = 0, otherB = 0;
  for (var k = 1; k <= cols; k++) {
    if (k !== cur && known[k]) { otherA += known[k][0]; otherB += known[k][1]; }
  }
  var html = '';
  for (var p = 1; p <= cols; p++) {
    var a, b, cls = '';
    if (p === cur) {
      a = Math.max(0, fieldInt('f1') - otherA); b = Math.max(0, fieldInt('f3') - otherB); cls = ' is-current';
    } else if (known[p]) {
      a = known[p][0]; b = known[p][1];
    } else if (p < cur) {
      a = 0; b = 0;
    } else {
      a = '\u2013'; b = '\u2013'; cls = ' is-future';
    }
    var head = p > reg ? fieldText('f13') : String(p);
    html += '<div class="scoreboard-pcell scoreboard-phead' + cls + '">' + escapeHtml(head) + '</div>'
          + '<div class="scoreboard-pcell' + cls + '">' + escapeHtml(a) + '</div>'
          + '<div class="scoreboard-pcell' + cls + '">' + escapeHtml(b) + '</div>';
  }
  wrap.innerHTML = html;
}

// syncPeriodLength(): f16 is where Reset clock returns to. A held clock still standing at the
// old length moves to the new one at once, so setting it before face-off needs no Reset.
function syncPeriodLength() {
  var el = matchClockEl();
  var len = fieldText('f16').trim();
  if (!el || len === '') return;
  var old = el.getAttribute('data-start') || '';
  if (old === len) return;
  el.setAttribute('data-start', len);
  if (matchClockReady && matchClockAt === null && matchClockBase === parseMatchClock(old)) {
    matchClockBase = parseMatchClock(len);
    paintMatchClock();
  }
}

function rebuildScoreboard() {
  applyTeamColours();
  paintMonograms();
  paintPeriodName();
  rebuildPeriods();
  syncPeriodLength();
  paintStatus();
}

// resetOnTake(): a fresh Take starts from the stylesheet's look, whatever the last run left.
function resetOnTake() {
  paintMatchState();
  rebuildScoreboard();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', rebuildScoreboard);
} else {
  rebuildScoreboard();
}

/* == ANIMATION'''
